class FenwickTree:
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 2)

    def update(self, i, delta):
        i += 1  # shift for one-based index
        while i < len(self.bit):
            self.bit[i] += delta
            i += i & -i

    def query(self, i):
        i += 1  # shift for one-based index
        res = 0
        while i > 0:
            res += self.bit[i]
            i -= i & -i
        return res

    def range_sum(self, l, r):
        return self.query(r) - self.query(l - 1)

def is_peak(nums, i):
    # Return whether position i is a peak (excluding endpoints)
    if i <= 0 or i >= len(nums) - 1:
        return 0
    return int(nums[i] > nums[i-1] and nums[i] > nums[i+1])

def peaks_in_array(nums, queries):
    n = len(nums)
    peak = [is_peak(nums, i) for i in range(n)]
    ft = FenwickTree(n)
    for i in range(n):
        if peak[i]:
            ft.update(i, 1)

    res = []
    for q in queries:
        if q[0] == 1:
            l, r = q[1], q[2]
            # peaks only at positions l+1 to r-1
            if r - l < 2:
                res.append(0)
            else:
                res.append(ft.range_sum(l+1, r-1))
        else:
            idx, val = q[1], q[2]
            nums[idx] = val
            # Only indices idx-1, idx, idx+1 can have changed peak status
            for j in (idx-1, idx, idx+1):
                if 0 < j < n-1:
                    new_peak = is_peak(nums, j)
                    if peak[j] != new_peak:
                        ft.update(j, new_peak - peak[j])
                        peak[j] = new_peak
    return res
